// SandboxServiceHandler is an implementation of the bean.node.v1.SandboxService service.
type SandboxServiceHandler interface {
	CreateSandbox(context.Context, *connect.Request[v1.CreateSandboxRequest]) (*connect.Response[v1.CreateSandboxResponse], error)
	DestroySandbox(context.Context, *connect.Request[v1.DestroySandboxRequest]) (*connect.Response[v1.DestroySandboxResponse], error)
	PauseSandbox(context.Context, *connect.Request[v1.PauseSandboxRequest]) (*connect.Response[v1.PauseSandboxResponse], error)
	ResumeSandbox(context.Context, *connect.Request[v1.ResumeSandboxRequest]) (*connect.Response[v1.ResumeSandboxResponse], error)
	GetSandbox(context.Context, *connect.Request[v1.GetSandboxRequest]) (*connect.Response[v1.GetSandboxResponse], error)
	// SnapshotSandbox streams a checkpoint out of the node. The sandbox is
	// frozen for the duration and returned to its prior state afterwards.
	SnapshotSandbox(context.Context, *connect.Request[v1.SnapshotSandboxRequest], *connect.ServerStream[v1.SnapshotChunk]) error
	// RestoreSandbox creates a sandbox from a checkpoint stream. The first
	// frame carries the spec; the rest is checkpoint data. A node that already
	// holds the checkpoint unpacked answers without reading the data frames, so
	// the sender must tolerate the stream being cut short.
	RestoreSandbox(context.Context, *connect.ClientStream[v1.RestoreSandboxFrame]) (*connect.Response[v1.RestoreSandboxResponse], error)
	StartUserProcess(context.Context, *connect.Request[v1.StartUserProcessNodeRequest]) (*connect.Response[v1.StartUserProcessNodeResponse], error)
	// PrewarmImage makes an image ready on the node without creating a sandbox.
	// A first pull can take minutes — longer than a create should block — so the
	// control plane warms images before placing work that needs them.
	PrewarmImage(context.Context, *connect.Request[v1.PrewarmImageRequest]) (*connect.Response[v1.PrewarmImageResponse], error)
	// StartBuild builds a base image from a Dockerfile. The build runs on the
	// node, where BuildKit and the image cache already are.
	//
	// It returns as soon as the build is registered and running, not when it
	// finishes: the build runs under a node-owned context (registered by tag),
	// not under this call's context, so it survives the caller -- a control-plane
	// replica may restart, or a follower may come and go, without killing the
	// build. Progress is read from the shared log store (any replica), the
	// outcome is polled via GetBuildStatus, and the build is stopped via
	// CancelBuild. This replaced the old BuildImage server stream, whose context
	// was the build's lifeline and so tied a build's life to one caller's.
	StartBuild(context.Context, *connect.Request[v1.BuildImageRequest]) (*connect.Response[v1.StartBuildResponse], error)
	// GetBuildStatus reports whether a build (addressed by tag) is still running,
	// succeeded (with its result), or failed (with a reason). The control plane
	// polls this after StartBuild until a terminal phase, then writes the
	// authoritative template state. An unknown tag reports BUILD_UNKNOWN rather
	// than an error, so a poll that races registration or a restart is harmless.
	GetBuildStatus(context.Context, *connect.Request[v1.GetBuildStatusRequest]) (*connect.Response[v1.GetBuildStatusResponse], error)
	// CancelBuild stops a build running on this node, addressed by its tag.
	//
	// It exists because a build no longer belongs to whoever holds the BuildImage
	// stream: the node writes the log to shared storage itself, so any control-plane
	// replica can follow a build, and any replica must therefore be able to stop one
	// it did not start. The node keeps a registry of in-flight builds keyed by tag
	// and cancels the matching one's context, which kills buildctl -- the same
	// mechanism aborting the stream used to trigger. Cancelling an unknown or
	// already-finished tag is not an error, so a racing double-cancel is harmless.
	CancelBuild(context.Context, *connect.Request[v1.CancelBuildRequest]) (*connect.Response[v1.CancelBuildResponse], error)
	// ConfigureAdmission updates the node's local admission thresholds (the disk
	// floor and memory ceiling that DiskGuard/MemGuard enforce on Create) at
	// runtime, so an operator can tighten or loosen a node without restarting it.
	//
	// It lives on SandboxService because that is bean's only control-plane->node
	// channel; the startup flags remain the initial default, and the control plane
	// re-pushes the current config after a node registers or reconnects so a
	// restarted node converges back to it rather than reverting to its flags. Only
	// the fields present in the AdmissionConfig are changed; an absent field leaves
	// that threshold as it was.
	ConfigureAdmission(context.Context, *connect.Request[v1.ConfigureAdmissionRequest]) (*connect.Response[v1.ConfigureAdmissionResponse], error)
	// Data plane passthrough to AgentService.
	Exec(context.Context, *connect.Request[v11.ExecRequest]) (*connect.Response[v11.ExecResponse], error)
	StreamExec(context.Context, *connect.BidiStream[v11.StreamExecFrame, v11.StreamExecFrame]) error
	ReadFile(context.Context, *connect.Request[v11.ReadFileRequest], *connect.ServerStream[v11.FileChunk]) error
	WriteFile(context.Context, *connect.ClientStream[v11.WriteFileFrame]) (*connect.Response[v11.WriteFileResponse], error)
	DeleteFile(context.Context, *connect.Request[v11.DeleteFileRequest]) (*connect.Response[v11.DeleteFileResponse], error)
	ListDir(context.Context, *connect.Request[v11.ListDirRequest]) (*connect.Response[v11.ListDirResponse], error)
	GetLogs(context.Context, *connect.Request[v11.GetLogsRequest], *connect.ServerStream[v11.LogChunk]) error
}

